  function gallerySheet(){const s=state(),items=live(s.gallery).filter(x=>x.dataUrl||x.url);openSheet(`<h2>共同相册</h2><p>上传新照片，或管理已经保存的共同照片。</p><input id="lifePhotoFile" type="file" accept="image/*"><textarea id="lifePhotoCaption" placeholder="写一句照片说明（可选）"></textarea><input class="life-sheet-input" id="lifePhotoUrl" placeholder="或粘贴图片链接 https://…"><button class="life-sheet-primary" data-save-photo>添加照片</button><div class="life-media-grid">${items.map(x=>`<article><img src="${esc(x.dataUrl||x.url)}" alt=""><button data-life-gallery-delete="${esc(x.id)}">删除</button><span>${esc(x.caption||'共同瞬间')}</span></article>`).join('')||'<div class="life-data-empty">还没有照片。</div>'}</div>`);}
  function messageSheet(){const s=state(),me=s.settings.me||'a',names=s.settings.partners||{},chats=live(s.messages).sort((a,b)=>(a.createdAt||0)-(b.createdAt||0)).slice(-40).map(m=>`<div class="life-chat ${m.author===me?'mine':''}">${m.image?`<img class="life-chat-image" src="${esc(m.image)}" alt="message image">`:''}${esc(m.text)}<time>${esc(m.author===me?(names[me]||'\u6211'):(names[m.author]||'TA'))} · ${esc(when(m.createdAt))}</time>${m.author===me?`<button data-life-message-delete="${esc(m.id)}">\u5220\u9664</button>`:''}</div>`).join('')||'<div class="life-data-empty">\u8fd8\u6ca1\u6709\u7559\u8a00\u3002</div>';const events=records(s).slice(0,16).map(x=>`<div class="life-row"><span class="life-icon">${icon(x.type==='\u968f\u624b\u62cd'?'image':'chat-circle-text')}</span><span class="life-row-main"><span class="life-label">${esc(when(x.time))} · ${esc(x.type)}</span><span class="life-value">${esc(x.body||x.title)}</span>${x.image?`<img class="life-record-image" src="${esc(x.image)}" alt="record image">`:''}</span></div>`).join('')||'<div class="life-data-empty">\u4eca\u5929\u8fd8\u6ca1\u6709\u65b0\u7684\u8bb0\u5f55\u3002</div>';openSheet(`<h2>\u7559\u7ed9\u4f60</h2><div class="life-inline-actions"><button data-life-identity="a" class="${me==='a'?'active':''}">${esc(names.a||'\u6210\u5458 A')}</button><button data-life-identity="b" class="${me==='b'?'active':''}">${esc(names.b||'\u6210\u5458 B')}</button><button data-life-notify>${s.settings.notifySystem===false?'\u5f00\u542f\u901a\u77e5':'\u901a\u77e5\u5df2\u5f00\u542f'}</button></div><div class="life-message-history">${chats}</div><textarea id="lifeMessageText" placeholder="\u5199\u70b9\u4ec0\u4e48\u7ed9 TA..."></textarea><input id="lifeMessageImage" type="file" accept="image/*"><button class="life-sheet-primary" data-save-message>\u53d1\u9001</button><h3 class="life-sheet-subtitle">\u4eca\u5929\u53d1\u751f\u4e86\u4ec0\u4e48</h3><div class="life-mini-list">${events}</div>`);}
  function wishSheet(){const s=state(),me=s.settings.me||'a',items=live(s.wishes).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).map(w=>`<article class="life-wish ${w.lit?'lit':''}"><span>${esc(w.icon||'✨')}</span><b>${esc(w.text)}</b><small>${esc(when(w.createdAt))}</small>${w.author===me?`<button data-life-wish-delete="${esc(w.id)}">删除</button>`:!w.lit?`<button data-light-wish="${esc(w.id)}">点亮</button>`:''}</article>`).join('')||'<div class="life-data-empty">心愿墙还是空的。</div>';openSheet(`<h2>心愿墙</h2><textarea id="lifeWishText" placeholder="写下一个小心愿…"></textarea><div class="life-inline-actions"><button class="active" data-life-wish-icon="✨">✨</button><button data-life-wish-icon="💛">💛</button><button data-life-wish-icon="🌙">🌙</button><button data-life-wish-icon="🎁">🎁</button><label><input id="lifeWishAnonymous" type="checkbox" checked> 匿名</label></div><button class="life-sheet-primary" data-save-wish>贴上心愿</button><div class="life-wish-grid">${items}</div>`);}
  function trainingSheet(edit){const s=state(),t=edit||{},items=live(s.trainings).sort((a,b)=>(b.date||'').localeCompare(a.date||'')||(b.createdAt||0)-(a.createdAt||0)).map(x=>`<div class="life-row"><span class="life-icon">${icon('barbell')}</span><button class="life-row-main life-row-button" data-life-train-edit="${esc(x.id)}"><span class="life-value">${esc(x.content)}</span><span class="life-label">${esc(x.date||'未设日期')} · ${esc(x.muscle||'训练')}</span></button><button class="life-row-action" data-life-train-delete="${esc(x.id)}">删除</button></div>`).join('')||'<div class="life-data-empty">还没有训练记录。</div>';if(edit!==undefined){openSheet(`<h2>${edit?'编辑训练':'记录训练'}</h2><textarea id="lifeTrainContent" placeholder="今天练了什么？">${esc(t.content||'')}</textarea><input class="life-sheet-input" id="lifeTrainDate" type="date" value="${esc(t.date||dayKey())}"><input class="life-sheet-input" id="lifeTrainMuscle" placeholder="部位，例如：胸肩" value="${esc(t.muscle||'')}"><input class="life-sheet-input" id="lifeTrainDuration" placeholder="时长（可选）" value="${esc(t.duration||'')}"><textarea id="lifeTrainNote" placeholder="备注（可选）">${esc(t.note||'')}</textarea><button class="life-sheet-primary" data-save-train="${esc(t.id||'')}">保存训练</button>`);return;}openSheet(`<h2>训练</h2><div class="life-inline-actions"><button data-life-train-add>记录训练</button><button data-life-plan>训练计划</button></div><div class="life-mini-list">${items}</div>`);}
  function planSheet(){const plan=(state().fitnessPlan)||{},labels=['周日','周一','周二','周三','周四','周五','周六'];openSheet(`<h2>训练计划</h2>${labels.map((label,day)=>`<label class="life-field-label">${label}</label><input class="life-sheet-input" data-life-plan-day="${day}" value="${esc(plan[day]?.name||'')}">`).join('')}<button class="life-sheet-primary" data-save-plan>保存计划</button>`);}
