  function waterPanel(s){const me=s.settings.me||'a',ta=me==='a'?'b':'a',w=(s.water&&s.water[dayKey()])||{},p=s.settings.partners||{},host=slot('today');host.insertAdjacentHTML('beforeend',`<section class="life-section"><div class="life-section-head"><h2 class="life-section-title">今日喝水</h2><span class="life-label">${esc(p[ta]||'TA')} ${Number(w[ta]||0)}/8</span></div><div class="life-water"><button data-life-water="-1">−</button><b>${Number(w[me]||0)} <small>/ 8 杯</small></b><button data-life-water="1">＋</button></div></section>`);}
