  function rebuildThings(s){const host=slot('things');if(!host)return;const me=(s.settings||{}).me||'a',photos=live(s.gallery).filter(x=>x.dataUrl||x.url),messages=live(s.messages).sort((a,b)=>(a.createdAt||0)-(b.createdAt||0)).slice(-3),wishes=live(s.wishes).sort((a,b)=>(b.createdAt||0)-(a.createdAt||0)).slice(0,4);const chat=messages.length?messages.map(m=>`<div class="life-chat ${m.author===me?'mine':''}">${esc(m.text)}<time>${esc(when(m.createdAt))}</time></div>`).join(''):'<div class="life-data-empty">还没有留言，写一句给对方吧。</div>';const wall=wishes.length?wishes.map(w=>`<article class="life-wish ${w.lit?'lit':''}"><span>${esc(w.icon||'♡')}</span><b>${esc(w.text)}</b><small>${esc(when(w.createdAt))}</small></article>`).join(''):'<div class="life-data-empty">心愿墙还是空的。</div>';host.innerHTML=`<header class="life-head"><div class="life-eyebrow">不必整理得很完美</div><h1 class="life-title">小事</h1><p class="life-sub">随手记住那些容易忘掉的瞬间。</p></header><section class="life-quick"><button class="life-quick-card" data-life-native="dashboard"><i class="life-quick-icon">${icon('image')}</i><b>共同照片</b><span>${photos.length?`已收好 ${photos.length} 张照片`:'保存此刻的光'}</span></button><button class="life-quick-card" data-life-native="fitness"><i class="life-quick-icon">${icon('barbell')}</i><b>训练记录</b><span>按同一天合并查看</span></button></section><section class="life-section"><div class="life-section-head"><h2 class="life-section-title">留给你</h2><button class="life-pill" data-life-native="messages">说句话</button></div><div class="life-inline-chat">${chat}</div></section><section class="life-section"><div class="life-section-head"><h2 class="life-section-title">小心愿墙</h2><button class="life-pill" data-life-native="wishes">查看全部</button></div><div class="life-things-wishes"><div class="life-wish-grid">${wall}</div></div></section>`;}
  function groupedTrainingSheet(){const groups={};live(state().trainings).forEach(x=>{const k=x.date||'未标注日期';(groups[k]||(groups[k]=[])).push(x);});const rows=Object.entries(groups).sort((a,b)=>b[0].localeCompare(a[0])).map(([date,items])=>`<button class="life-row life-training-day" data-life-train-day="${esc(date)}"><span class="life-icon">${icon('barbell')}</span><span class="life-row-main"><span class="life-value">${esc(date)} · ${items.length} 条训练</span><span class="life-label">${esc(items.map(x=>x.muscle||x.content||'训练记录').join(' · ').slice(0,70))}</span></span><span class="life-row-action">查看</span></button>`).join('')||'<div class="life-data-empty">还没有训练记录。</div>';openSheet(`<h2>训练记录</h2><p>同一天的训练已经合在一起，点开再看详情。</p><div class="life-mini-list">${rows}</div><div class="life-inline-actions"><button data-life-train-add>记录训练</button><button data-life-plan>训练计划</button></div>`);}
