  function render(){ const s=state(); if(!s)return; today(s);const pet=slot('today').querySelector('.life-pet');if(pet){pet.src=`assets/${weatherInfo(s).pet}`;pet.onclick=()=>{const card=pet.closest('.life-weather');card.classList.remove('life-pet-love');void card.offsetWidth;card.classList.add('life-pet-love');};}insertTodayPhotoHero(s);days(s);renderTodoPanel(s);tidyDays();slot('days').querySelector('.life-all-todos .life-section-head')?.insertAdjacentHTML('beforeend','<button class="life-pill" data-life-todo-export>导出</button>');things(s);rebuildThings(s);us(s);enhance(s);enhanceFortune(s);quickStatuses(s);enhanceStatusPets(s);waterPanel(s); }
