  root.addEventListener('click',e=>{const n=e.target.closest('[data-life-native]');if(!n||n.dataset.lifeNative!=='fitness')return;e.stopImmediatePropagation();const groups={};live(state().trainings).forEach(x=>{const k=x.date||'未标注日期';(groups[k]||(groups[k]=[])).push(x);});const cards=Object.entries(groups).sort((a,b)=>b[0].localeCompare(a[0])).map(([date,items])=>`<div class="life-horo"><b>${esc(date)} · ${items.length} 条训练</b><p>${esc(items.map(x=>x.muscle||x.content||'训练记录').join(' · ').slice(0,90))}</p></div>`).join('')||'<div class="life-data-empty">还没有训练记录。</div>';openSheet(`<h2>训练记录</h2><p>按当天整合，不重复堆叠动作。</p>${cards}`);},true);
